import{_ as r,o as a,c as e,ag as o}from"./chunks/framework.BjY7aUvS.js";const c=JSON.parse('{"title":"买药防坑 · 药品比价与追溯码","description":"买药两把官方尺子：医保药品比价（同药不同店价差可查）与药品追溯码扫码（防\\"回流药\\"），附集采、网售药避坑要点。","frontmatter":{"title":"买药防坑 · 药品比价与追溯码","issuer":"国家医疗保障局 / 国家药品监督管理局","source_tier":"一级来源","version":"—","published":"—","source_url":"https://fuwu.nhsa.gov.cn/","status":"现行服务","tags":["官方查询","药品比价","追溯码","回流药","买药","防坑"],"type":"查询页","reviewed":false,"description":"买药两把官方尺子：医保药品比价（同药不同店价差可查）与药品追溯码扫码（防\\"回流药\\"），附集采、网售药避坑要点。"},"headers":[],"relativePath":"query/drug-price.md","filePath":"query/drug-price.md"}'),d={name:"query/drug-price.md"};function n(s,t,h,l,u,i){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="买药防坑-·-药品比价与追溯码" tabindex="-1">买药防坑 · 药品比价与追溯码 <a class="header-anchor" href="#买药防坑-·-药品比价与追溯码" aria-label="Permalink to &quot;买药防坑 · 药品比价与追溯码&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页由 AI 会话信息整理；比价与追溯码功能在<strong>各地分批上线</strong>，以国家医保服务平台 App 与当地医保局口径为准。</p></div><blockquote><p><strong>官方入口</strong>：<a href="https://fuwu.nhsa.gov.cn/" target="_blank" rel="noreferrer">国家医保服务平台</a> App（药品比价、追溯码扫码在部分/多数地区已上线，待核验）；各地医保局小程序。· 一级来源</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>买药两把官方尺子：<strong>比价</strong>——同一通用名药品，附近药店/医院卖多少钱一目了然，别当&quot;冤大头&quot;；<strong>追溯码</strong>——药盒上的追溯码扫码验明&quot;出身&quot;，专防<strong>回流药</strong>（从医保套出来的药再倒卖回市场，储存运输无保障）。</p><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>买药前：<a href="https://fuwu.nhsa.gov.cn/" target="_blank" rel="noreferrer">国家医保服务平台</a> App 查<strong>药品比价</strong>（输入通用名，比附近药店/医院价格）</td><td>待核验</td></tr><tr><td>拿到药后：医保 App <strong>扫药盒追溯码</strong>——显示&quot;已售/首次销售&quot;等信息；<strong>被扫过多次的码 = 高度疑似回流药</strong>，可拒收并举报</td><td>待核验</td></tr><tr><td>认准<strong>集采中选药品</strong>：国家集采让同成分药价大幅下降，医院/药店有售，效果一致性有评价（待核验）</td><td>国家医保局</td></tr><tr><td>网购药品：平台需展示《药品网络交易服务备案》资质；<strong>处方药必须凭处方</strong></td><td>药监局规定</td></tr></tbody></table><h2 id="避坑要点" tabindex="-1">避坑要点 <a class="header-anchor" href="#避坑要点" aria-label="Permalink to &quot;避坑要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>骗局话术</th><th>官方事实</th></tr></thead><tbody><tr><td>&quot;高价回收药品/医保卡套现&quot;</td><td>回收倒卖医保药品<strong>违法</strong>，且这些&quot;回流药&quot;来源贮存不明——不卖不买</td></tr><tr><td>&quot;微商代购国外特效药&quot;</td><td>无批准文号的境外药品按假药论处，见<a href="/SageRelay/query/drug.html">药品批准文号查询</a></td></tr><tr><td>&quot;比价麻烦，反正医保报&quot;</td><td>医保基金是全家的钱袋，价格差最终影响报销池与个人自付</td></tr><tr><td>【本站提示】慢病长期用药：结合<a href="/SageRelay/guides/hypertension-2023.html">慢病食养词条</a>把生活方式干预做足，用药方案永远听医生的</td><td>—</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li>药品真伪：<a href="/SageRelay/query/drug.html">药品批准文号查询</a> · 报销资格：<a href="/SageRelay/query/yibao.html">医保定点</a> · <a href="/SageRelay/query/yibao-drug.html">医保药品目录</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>平台</td><td>国家医保局国家医保服务平台（一级来源）</td></tr><tr><td>入口</td><td><a href="https://fuwu.nhsa.gov.cn/" target="_blank" rel="noreferrer">fuwu.nhsa.gov.cn</a>（已核验可达）· 12393</td></tr></tbody></table>',13)])])}const p=r(d,[["render",n]]);export{c as __pageData,p as default};
